create or replace function apply_schedule_daily_overlay_v1(p_date date,p_operations jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare op jsonb;k text;gid uuid:=gen_random_uuid();oid uuid;src_id uuid;al_id uuid;al absence_lessons%rowtype;ts teacher_schedule%rowtype;eff_teacher uuid;eff_period smallint;eff_class uuid;eff_classes uuid[];eff_room uuid;eff_subgroup uuid;eff_subject text;eff_class_name text;emit boolean;n int:=0;split_count int;join_count int;join_emit int;begin if not(is_manager_or_admin() or has_permission('schedule.edit') or has_permission('substitutes.manage')) then raise exception 'NOT_AUTHORIZED';end if;if jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations)=0 then raise exception 'OPERATIONS_REQUIRED';end if;select count(*) filter(where upper(x->>'operation_kind')='SPLIT'),count(*) filter(where upper(x->>'operation_kind')='JOIN'),count(*) filter(where upper(x->>'operation_kind')='JOIN' and coalesce((x->>'emits_event')::boolean,true)) into split_count,join_count,join_emit from jsonb_array_elements(p_operations)x;if split_count=1 then raise exception 'SPLIT_REQUIRES_MULTIPLE_PARTS';end if;if join_count>0 and(join_count<2 or join_emit<>1) then raise exception 'JOIN_REQUIRES_MULTIPLE_SOURCES_AND_ONE_EMIT';end if;perform pg_advisory_xact_lock(hashtext(current_tenant_code()||':'||p_date::text));for op in select * from jsonb_array_elements(p_operations) loop k:=upper(coalesce(op->>'operation_kind',''));if k not in('COVER','MOVE','SWAP','CANCEL','CREATE','SPLIT','JOIN') then raise exception 'INVALID_OPERATION_KIND';end if;src_id:=nullif(op->>'source_schedule_id','')::uuid;al_id:=nullif(op->>'source_absence_lesson_id','')::uuid;if al_id is not null then select * into al from absence_lessons where id=al_id and lesson_date=p_date and tenant_row_allowed(institution_code);if not found then raise exception 'ABSENCE_LESSON_NOT_FOUND';end if;if src_id is null then src_id:=al.source_schedule_id;end if;else al:=null;end if;if src_id is not null then select * into ts from teacher_schedule where id=src_id and active and tenant_row_allowed(institution_code);if not found then raise exception 'SOURCE_SCHEDULE_NOT_FOUND';end if;else ts:=null;end if;if k<>'CREATE' and src_id is null and al_id is null and coalesce((op->>'emit_only')::boolean,false)=false then raise exception 'SOURCE_REQUIRED';end if;eff_teacher:=coalesce(nullif(op->>'effective_teacher_id','')::uuid,case when al_id is not null then al.teacher_id else ts.teacher_id end);eff_period:=coalesce(nullif(op->>'effective_period','')::smallint,case when al_id is not null then al.period else ts.period end);eff_class:=coalesce(nullif(op->>'effective_class_id','')::uuid,case when al_id is not null then al.class_id else ts.class_id end);if op?'effective_class_ids' then select coalesce(array_agg(v::uuid),'{}'::uuid[]) into eff_classes from jsonb_array_elements_text(op->'effective_class_ids')v;else eff_classes:=array_remove(array[eff_class],null)::uuid[];end if;eff_room:=coalesce(nullif(op->>'effective_classroom_id','')::uuid,case when al_id is not null then al.classroom_id else ts.classroom_id end);eff_subgroup:=coalesce(nullif(op->>'effective_subgroup_id','')::uuid,case when al_id is not null then al.subgroup_id else ts.subgroup_id end);eff_subject:=coalesce(nullif(op->>'effective_subject',''),case when al_id is not null then al.subject else ts.subject end);eff_class_name:=coalesce(nullif(op->>'effective_class_name',''),case when al_id is not null then al.class_name else ts.class_name end);emit:=coalesce((op->>'emits_event')::boolean,k<>'CANCEL');if k='COVER' then if al_id is null or eff_teacher is null then raise exception 'COVER_REQUIRES_ABSENCE_AND_TEACHER';end if;if not exists(select 1 from get_substitute_candidates_v4(al_id)c where c.candidate_user_id=eff_teacher and c.feasible) then raise exception 'SUBSTITUTE_NOT_FEASIBLE';end if;end if;insert into schedule_daily_overlays(institution_code,overlay_date,operation_group_id,operation_kind,source_absence_lesson_id,source_schedule_id,effective_teacher_id,effective_period,effective_class_id,effective_class_ids,effective_classroom_id,effective_subgroup_id,effective_subject,effective_class_name,emits_event,payload,created_by) values(current_tenant_code(),p_date,gid,k,al_id,src_id,case when emit then eff_teacher else null end,case when emit then eff_period else null end,case when emit then eff_class else null end,case when emit then eff_classes else null end,case when emit then eff_room else null end,case when emit then eff_subgroup else null end,case when emit then eff_subject else null end,case when emit then eff_class_name else null end,emit,coalesce(op->'payload','{}'::jsonb),auth.uid()) returning id into oid;if k='COVER' then insert into substitute_assignments(absence_lesson_id,substitute_user_id,assigned_by,institution_code,overlay_id,reason,approval_status,approved_by,approved_at) values(al_id,eff_teacher,auth.uid(),current_tenant_code(),oid,coalesce(op->>'reason','V4 canonical cover'),'approved',auth.uid(),now()) on conflict(absence_lesson_id) do update set substitute_user_id=excluded.substitute_user_id,assigned_by=excluded.assigned_by,assigned_at=now(),overlay_id=excluded.overlay_id,reason=excluded.reason,approval_status='changed',approved_by=excluded.approved_by,approved_at=excluded.approved_at;end if;n:=n+1;end loop;perform assert_schedule_daily_overlay_hard_v1(p_date);update absences a set status='planned' where a.absence_date=p_date and tenant_row_allowed(a.institution_code) and not exists(select 1 from absence_lessons al left join substitute_assignments sa on sa.absence_lesson_id=al.id and sa.active where al.teacher_id=a.teacher_id and al.lesson_date=a.absence_date and tenant_row_allowed(al.institution_code) and sa.id is null);return jsonb_build_object('operation_group_id',gid,'operations',n);end$$;
create or replace function revert_schedule_daily_overlay_v1(p_operation_group_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare d date;n int;begin if not(is_manager_or_admin() or has_permission('schedule.edit') or has_permission('substitutes.manage')) then raise exception 'NOT_AUTHORIZED';end if;select overlay_date into d from schedule_daily_overlays where operation_group_id=p_operation_group_id and status='ACTIVE' and tenant_row_allowed(institution_code) limit 1;if d is null then raise exception 'ACTIVE_OVERLAY_GROUP_NOT_FOUND';end if;perform pg_advisory_xact_lock(hashtext(current_tenant_code()||':'||d::text));update substitute_assignments sa set active=false,approval_status='rejected',approved_by=auth.uid(),approved_at=now() where sa.active and sa.overlay_id in(select id from schedule_daily_overlays where operation_group_id=p_operation_group_id and tenant_row_allowed(institution_code));update schedule_daily_overlays set status='REVERTED',reverted_by=auth.uid(),reverted_at=now() where operation_group_id=p_operation_group_id and status='ACTIVE' and tenant_row_allowed(institution_code);get diagnostics n=row_count;update absences a set status='open' where a.absence_date=d and tenant_row_allowed(a.institution_code) and exists(select 1 from absence_lessons al where al.teacher_id=a.teacher_id and al.lesson_date=d and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active));perform assert_schedule_daily_overlay_hard_v1(d);insert into schedule_daily_overlay_audit(institution_code,operation_group_id,overlay_date,action,detail,actor) values(current_tenant_code(),p_operation_group_id,d,'REVERT',jsonb_build_object('rows',n),auth.uid());return jsonb_build_object('reverted',n,'operation_group_id',p_operation_group_id);end$$;
create or replace function assign_substitutes_for_day_v4(p_date date default current_date) returns jsonb language plpgsql security definer set search_path=public as $$declare l record;c record;r jsonb;assigned int:=0;uncovered int:=0;begin if not(is_manager_or_admin() or has_permission('substitutes.manage')) then raise exception 'NOT_AUTHORIZED';end if;for l in select al.id from absence_lessons al where al.lesson_date=p_date and tenant_row_allowed(al.institution_code) and not exists(select 1 from substitute_assignments sa where sa.absence_lesson_id=al.id and sa.active) order by al.period,al.class_name loop select * into c from get_substitute_candidates_v4(l.id) where feasible order by rank_score,candidate_user_id limit 1;if found then r:=apply_schedule_daily_overlay_v1(p_date,jsonb_build_array(jsonb_build_object('operation_kind','COVER','source_absence_lesson_id',l.id,'effective_teacher_id',c.candidate_user_id,'reason','V4 direct cover')));assigned:=assigned+1;else uncovered:=uncovered+1;end if;end loop;return jsonb_build_object('assigned',assigned,'uncovered',uncovered);end$$;
create or replace function apply_substitution_chain_v4(p_absence_lesson_id uuid,p_primary_teacher_id uuid,p_cover_teacher_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare d date;per smallint;busy uuid;ops jsonb;begin if not(is_manager_or_admin() or has_permission('substitutes.manage')) then raise exception 'NOT_AUTHORIZED';end if;select lesson_date,period into d,per from absence_lessons where id=p_absence_lesson_id and tenant_row_allowed(institution_code);if d is null then raise exception 'ABSENCE_LESSON_NOT_FOUND';end if;select e.source_schedule_id into busy from get_schedule_daily_effective_v1(d)e where e.teacher_id=p_primary_teacher_id and e.period=per and not e.is_overlay and e.source_schedule_id is not null limit 1;if busy is null then raise exception 'PRIMARY_TEACHER_NOT_BUSY_ON_BASE_EVENT';end if;if not exists(select 1 from get_event_cover_candidates_v1(d,busy)c where c.candidate_user_id=p_cover_teacher_id and c.feasible) then raise exception 'CHAIN_COVER_TEACHER_NOT_FEASIBLE';end if;ops:=jsonb_build_array(jsonb_build_object('operation_kind','SWAP','source_schedule_id',busy,'effective_teacher_id',p_cover_teacher_id,'effective_period',per,'payload',jsonb_build_object('chain_role','release_primary')),jsonb_build_object('operation_kind','COVER','source_absence_lesson_id',p_absence_lesson_id,'effective_teacher_id',p_primary_teacher_id,'reason','V4 chain cover','payload',jsonb_build_object('chain_role','cover_absence')));return apply_schedule_daily_overlay_v1(d,ops);end$$;